#include <openssl/sha.h>
#include <cstdint>
constexpr uint64_t ZAXIS = 69885998345277ULL; // 0x3F8F9A1B2C3D
constexpr int STRIDE = 17684;
constexpr int P0 = 57000;
constexpr uint32_t CRC_POLY = 0xedb88320;
constexpr uint32_t GROUND_31_MASK = 0x7FFFFFFF;
constexpr uint8_t APEX_7_MASK = 0x7F;
// A(r) = r * S
// Phi(r,k) = (r * S) mod 2^k
inline uint64_t lane_address(uint64_t r) { return r * STRIDE; }
inline uint64_t phi_drift(uint64_t r, int k) { return (r * STRIDE) & ((1ULL << k) - 1); }
